import triton.language as tl


def _compute_output_size(input_size, kernel_size, stride, padding, dilation):
    return (input_size - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_W": 16, "BLOCK_OC": 32},
        ),
    ],
    key=["W_act", "C_out"],
)
@triton.jit
def _conv_transpose3d_v5(
    x_ptr,
    w_ptr,
    out_ptr,
    D: tl.constexpr,
    H: tl.constexpr,
    W: tl.constexpr,
    C_out: tl.constexpr,
    D_out: tl.constexpr,
    H_out: tl.constexpr,
    W_out: tl.constexpr,
    D_act: tl.constexpr,
    H_act: tl.constexpr,
    W_act: tl.constexpr,
    sx_b,
    sx_d,
    sx_h,
    sx_w,
    so_b,
    so_d,
    so_h,
    so_w,
    BLOCK_W: tl.constexpr,
    BLOCK_OC: tl.constexpr,
    K: tl.constexpr,
    C_IN: tl.constexpr,
):
    pid_w = tl.program_id(0)
    pid_bdh = tl.program_id(1)
    pid_oc = tl.program_id(2)

    b = pid_bdh // (D_act * H_act)
    rem = pid_bdh % (D_act * H_act)
    d_idx = rem // H_act
    h_idx = rem % H_act

    offs_w_idx = pid_w * BLOCK_W + tl.arange(0, BLOCK_W)
    offs_oc = pid_oc * BLOCK_OC + tl.arange(0, BLOCK_OC)

    acc = tl.zeros((BLOCK_W, BLOCK_OC), dtype=tl.float32)

    x_batch_base = x_ptr + b.to(tl.int64) * sx_b

    for kd in range(K):
        d_in = d_idx + 1 - kd
        d_ok = (d_in >= 0) & (d_in < D)
        if d_ok:
            for kh in range(K):
                h_in = h_idx + 1 - kh
                h_ok = (h_in >= 0) & (h_in < H)
                if h_ok:
                    x_dh_base = x_batch_base + d_in * sx_d + h_in * sx_h

                    for kw in range(K):
                        w_in_start = pid_w * BLOCK_W + 1 - kw

                        x_bp = tl.make_block_ptr(
                            base=x_dh_base,
                            shape=(W, C_IN),
                            strides=(sx_w, 1),
                            offsets=(w_in_start, 0),
                            block_shape=(BLOCK_W, C_IN),
                            order=(1, 0),
                        )
                        x_tile = tl.load(
                            x_bp, boundary_check=(0,), padding_option="zero"
                        )

                        kidx = kd * K * K + kh * K + kw
                        w_bp = tl.make_block_ptr(
                            base=w_ptr + kidx * C_IN * C_out,
                            shape=(C_IN, C_out),
                            strides=(C_out, 1),
                            offsets=(0, pid_oc * BLOCK_OC),
                            block_shape=(C_IN, BLOCK_OC),
                            order=(1, 0),
                        )
                        w_tile = tl.load(
                            w_bp, boundary_check=(1,), padding_option="zero"
                        )

                        acc += tl.dot(x_tile, w_tile)

    d_out = 2 * d_idx + 1
    h_out = 2 * h_idx + 1
    w_out = 2 * offs_w_idx + 1
    out_base = out_ptr + b.to(tl.int64) * so_b + d_out * so_d + h_out * so_h
    out_ptrs = out_base + w_out[:, None] * so_w + offs_oc[None, :]
    out_mask = (offs_w_idx[:, None] < W_act) & (offs_oc[None, :] < C_out)
    tl.store(out_ptrs, acc.to(tl.float16), mask=out_mask)


@triton.jit
def _zero_kernel(out_ptr, N, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    tl.store(out_ptr + offs, tl.zeros((BLOCK,), dtype=tl.float16), mask=mask)


class Model(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        bias: bool = False,
    ):
        super(Model, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            dilation=dilation,
            bias=bias,
        )
        self._packed = False
        self._buf_allocated = False

    def _pack_weights(self):
        w = self.conv_transpose3d.weight.data
        K = self.kernel_size
        self.weight_packed = (
            w.permute(2, 3, 4, 0, 1)
            .reshape(K * K * K, self.in_channels, self.out_channels)
            .contiguous()
            .to(dtype=torch.float16)
        )
        self._packed = True

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not self._packed:
            self._pack_weights()

        device = x.device
        B, C_in, D, H, W = x.shape
        K = self.kernel_size

        D_out = _compute_output_size(D, K, self.stride, self.padding, self.dilation)
        H_out = _compute_output_size(H, K, self.stride, self.padding, self.dilation)
        W_out = _compute_output_size(W, K, self.stride, self.padding, self.dilation)

        D_act = D_out // 2
        H_act = H_out // 2
        W_act = W_out // 2

        x_cl3d = x.to(dtype=torch.float16).contiguous(
            memory_format=torch.channels_last_3d
        )

        if not self._buf_allocated or self._output_buf.shape[0] != B:
            self._output_buf = torch.empty(
                B,
                self.out_channels,
                D_out,
                H_out,
                W_out,
                device=device,
                dtype=torch.float16,
            ).contiguous(memory_format=torch.channels_last_3d)
            self._buf_allocated = True

        output = self._output_buf
        N = output.numel()
        BLOCK = 32
        _zero_kernel[(triton.cdiv(N, BLOCK),)](output, N, BLOCK=BLOCK)

        sx = x_cl3d.stride()
        so = output.stride()

        grid = lambda META: (
            triton.cdiv(W_act, META["BLOCK_W"]),
            B * D_act * H_act,
            triton.cdiv(self.out_channels, META["BLOCK_OC"]),
        )

        _conv_transpose3d_v5[grid](
            x_cl3d,
            self.weight_packed,
            output,
            D,
            H,
            W,
            self.out_channels,
            D_out,
            H_out,
            W_out,
            D_act,
            H_act,
            W_act,
            sx[0],
            sx[2],
            sx[3],
            sx[4],
            so[0],
            so[2],
            so[3],
            so[4],
            K=K,
            C_IN=C_in,
        )

        return output
